const memoriaBruta = Array.isArray($json.memoria_nome_contato) ? $json.memoria_nome_contato : [];

function normalizar(v) {
  return String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
}
function clonar(v) {
  if (v && typeof v === 'object') return JSON.parse(JSON.stringify(v));
  try { return JSON.parse(String(v)); } catch { return null; }
}

const base = {
  ...dados,
  memoria_original: memoriaBruta,
  memoria_atualizada: memoriaBruta,
  nome_contato_validado: nomeAtual,
  atualizar_nome_memoria: false,
  acao_nome_memoria: 'IGNORAR',
  motivo_nome_memoria: ''
};

if (!nomeAtual) return [{ json: { ...base, motivo_nome_memoria: 'sem_nome_validado_pela_ia' } }];

const memoriaAtualizada = [...memoriaBruta];
let indiceSistema = -1;
let objetoSistema = null;
let conteudoSistema = '';

for (let i = 0; i < memoriaBruta.length; i++) {
  const entrada = clonar(memoriaBruta[i]);
  if (!entrada) continue;
  const tipo = String(entrada.type ?? entrada._getType ?? '').toLowerCase();
  const conteudo = String(entrada.data?.content ?? entrada.content ?? entrada.text ?? '');
  if (tipo === 'system' || /contexto fixo do lead/i.test(conteudo)) {
    indiceSistema = i;
    objetoSistema = entrada;
    conteudoSistema = conteudo;
    break;
  }
}

if (indiceSistema >= 0 && objetoSistema) {
  const match = conteudoSistema.match(/^Nome:\s*(.*)$/im);
  const nomeAnterior = String(match?.[1] ?? '').trim();
  if (normalizar(nomeAnterior) === normalizar(nomeAtual)) {
    return [{ json: { ...base, nome_memoria_anterior: nomeAnterior, motivo_nome_memoria: 'nome_ja_atualizado' } }];
  }

  let novoConteudo;
  if (match) novoConteudo = conteudoSistema.replace(/^Nome:\s*.*$/im, `Nome: ${nomeAtual}`);
  else if (/^Contexto fixo do lead:\s*$/im.test(conteudoSistema)) {
    novoConteudo = conteudoSistema.replace(/^Contexto fixo do lead:\s*$/im, `Contexto fixo do lead:\nNome: ${nomeAtual}`);
  } else novoConteudo = `Nome: ${nomeAtual}\n${conteudoSistema}`.trim();

  if (objetoSistema.data && typeof objetoSistema.data === 'object') objetoSistema.data.content = novoConteudo;
  else if ('content' in objetoSistema) objetoSistema.content = novoConteudo;
  else objetoSistema.data = { content: novoConteudo, additional_kwargs: {}, response_metadata: {} };

  objetoSistema.type = 'system';
  memoriaAtualizada[indiceSistema] = JSON.stringify(objetoSistema);
  return [{ json: { ...base, memoria_atualizada: memoriaAtualizada, nome_memoria_anterior: nomeAnterior, atualizar_nome_memoria: true, acao_nome_memoria: 'ATUALIZAR_LISTA', motivo_nome_memoria: nomeAnterior ? 'nome_diferente' : 'linha_nome_ausente' } }];
}

const nova = JSON.stringify({
  type: 'system',
  data: { content: `Contexto fixo do lead:\nNome: ${nomeAtual}`, additional_kwargs: {}, response_metadata: {} }
});
return [{ json: { ...base, memoria_atualizada: [...memoriaBruta, nova], nova_mensagem_sistema: nova, atualizar_nome_memoria: true, acao_nome_memoria: 'ADICIONAR_SYSTEM', motivo_nome_memoria: memoriaBruta.length ? 'mensagem_system_ausente' : 'memoria_vazia' } }];

