  const atual = String(r['Teve interesse'] || '').trim(); 

  // Se já consta como 'Sim', mantém
  if (atual.toLowerCase() === 'sim') return 'Sim'; 

  // Busca o texto do nó de forma segura
  const rawMsg = $('msgs agrupadas').first()?.json?.lista_msgs || '';

  // Normaliza o texto (remove acentos, pontuações e espaços extras)
  const t = String(rawMsg)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim(); 

  // Validação de desinteresse
  const negativo = /(nao tenho interesse|sem interesse|nao quero|pode parar|remover meu numero|nao me chame|cancelar contato|agora nao)/i.test(t);
  if (negativo) return 'Não';

  // Validação de interesse
  const positivo = /(saber mais|tenho interesse|quero economizar|como funciona|mais informacoes|quero uma simulacao|quero conhecer|pode me explicar|gostaria de saber|continuar|vamos continuar|pode mandar|me explica|quero entender|quero)/i.test(t);

  const valorDireto = /^(?:(?:uns?|aproximadamente|aprox|cerca de|mais ou menos|quase)\s+)?(?:r\$\s*)?\d[\d.,]*\s*(?:reais?|mil|k)?$/i.test(t) || /(?:conta|fatura|energia|luz).{0,30}(?:r\$\s*)?\d[\d.,]*/i.test(t); 

  if (positivo || valorDireto) return 'Sim'; 

  return atual; 
})() }}

