(() => {
  function extrairTexto(valor) {
    if (valor === undefined || valor === null) return '';

    if (Array.isArray(valor)) {
      return valor
        .map(extrairTexto)
        .filter(Boolean)
        .join('\n\n');
    }

    if (typeof valor === 'object') {
      return extrairTexto(
        valor.output ??
        valor.mensagem ??
        valor.message ??
        valor.text ??
        valor.body?.text ??
        ''
      );
    }

    return String(valor).trim();
  }

  let text = extrairTexto(
    $json.output ??
    $json.mensagem ??
    $json.message ??
    $json.text ??
    $json.mensagens ??
    $json.body?.text ??
    ''
  );

  // Limpeza básica
  text = text
    .replace(/```(?:json)?/gi, '')
    .replace(/```/g, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (!text) return [];

  // Se vier JSON em formato de texto,
  // tenta recuperar somente a mensagem.
  if (
    (text.startsWith('{') && text.endsWith('}')) ||
    (text.startsWith('[') && text.endsWith(']'))
  ) {
    try {
      const parsed = JSON.parse(text);

      text = extrairTexto(
        parsed.output ??
        parsed.mensagem ??
        parsed.message ??
        parsed.text ??
        parsed.mensagens ??
        parsed.body?.text ??
        parsed
      )
        .replace(/\r\n/g, '\n')
        .replace(/[ \t]+/g, ' ')
        .replace(/\n{4,}/g, '\n\n')
        .trim();

    } catch {}
  }

  if (!text) return [];

  // Cada parágrafo separado por linha em branco
  // representa uma bolha do WhatsApp.
  let blocos = text
    .split(/\n\s*\n/)
    .map(p => p.trim())
    .filter(Boolean);

  // Junta apenas saudações REALMENTE isoladas.
  // Não usa mais tamanho da mensagem como critério.
  const fillerCurto =
    /^(oi+|ol[aá]|opa|entendi|certo|beleza|perfeito|claro|sim|show|ótimo|obrigad[oa])[!,.\s😊🙂😉]*$/i;

  if (
    blocos.length > 1 &&
    fillerCurto.test(blocos[0])
  ) {
    blocos[1] = `${blocos[0]} ${blocos[1]}`
      .replace(/\s+/g, ' ')
      .trim();

    blocos.shift();
  }

  // Se a IA mandar mais de 4 parágrafos,
  // mantém os dois primeiros e junta o restante na terceira bolha.
  if (blocos.length > 4) {
    blocos = [
      blocos[0],
      blocos[1],
      blocos.slice(2).join('\n\n')
    ];
  }

  // Retorna no máximo 4 bolhas.
  return blocos.slice(0, 4);
})()
}}

