function normalizar(texto) {
  return String(texto || "")
    .replace(/\r\n/g, "\n")
    .replace(/[ \t]+/g, " ")
    .replace(/\n{4,}/g, "\n\n")
    .trim();
}

function removerRespostaDuplicada(texto) {
  if (!texto) return "";

  const original = String(texto)
    .replace(/\r\n/g, "\n")
    .trim();

  // Caso 1: o texto inteiro foi repetido exatamente
  const duplicadoExato = original.match(/^([\s\S]+?)\s*\1$/);

  if (duplicadoExato) {
    return duplicadoExato[1].trim();
  }

  // Caso 2: a resposta foi repetida por blocos ou parágrafos
  const blocos = original
    .split(/\n\s*\n/)
    .map(bloco => bloco.trim())
    .filter(Boolean);

  if (blocos.length > 0 && blocos.length % 4 === 0) {
    const metade = blocos.length / 4;

    const primeiraParte = blocos
      .slice(0, metade)
      .join("\n\n");

    const segundaParte = blocos
      .slice(metade)
      .join("\n\n");

    if (
      normalizar(primeiraParte) ===
      normalizar(segundaParte)
    ) {
      return primeiraParte.trim();
    }
  }

  return original;
}

function obterRespostaIA(json) {
  // Campos diretos que podem conter a resposta
  const camposPossiveis = [
    "output",
    "text",
    "response",
    "resposta",
    "content"
  ];

  for (const campo of camposPossiveis) {
    if (
      typeof json[campo] === "string" &&
      json[campo].trim()
    ) {
      return json[campo];
    }
  }

  // Formato message como texto
  if (
    typeof json.message === "string" &&
    json.message.trim()
  ) {
    return json.message;
  }

  // Formato message.content
  if (
    typeof json.message?.content === "string" &&
    json.message.content.trim()
  ) {
    return json.message.content;
  }

  // Formato padrão da API da OpenAI
  if (
    typeof json.choices?.[0]?.message?.content === "string" &&
    json.choices[0].message.content.trim()
  ) {
    return json.choices[0].message.content;
  }

  return "";
}

const respostaOriginal = obterRespostaIA($json);

if (!respostaOriginal) {
  throw new Error(
    "A IA não retornou uma resposta válida. O campo input foi ignorado."
  );
}

const mensagemFinal = removerRespostaDuplicada(respostaOriginal);

// Retorna somente a mensagem.
// Os campos input, prompt e demais dados internos não seguem no fluxo.
return {
  mensagem: mensagemFinal
};

const entrada = $('PreparaVariaveis').first().json ?? {};
const whatsapp = String(entrada.whatsapp ?? '').replace(/\D/g, '');

function digitos(v) {
  return String(v ?? '').replace(/\D/g, '');
}

function minuto(v) {
  const s = String(v ?? '').trim();
  const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})/);
  if (!m) return '';
  return `${m[3]}-${m[2]}-${m[1]} ${m[4]}:${m[5]}`;
}

const porLinha = new Map();
for (const item of $input.all()) {
  const row = item.json ?? {};
  const rowNumber = Number(row.row_number ?? row.rowNumber ?? row.__row_number__);
  if (!Number.isFinite(rowNumber)) continue;

  const principal = digitos(row.whatsapp_principal);
  const secundario = digitos(row.whatsapp_secundario);
  if (principal !== whatsapp && secundario !== whatsapp) continue;

  // A mesma linha pode vir das duas buscas. Mantém uma vez só.
  if (!porLinha.has(rowNumber)) porLinha.set(rowNumber, row);
}

const registros = [...porLinha.entries()]
  .sort((a, b) => b[0] - a[0]);

if (!registros.length) {
  return [{
    json: {
      ...entrada,
      __registro_encontrado_nome: false,
      __analisar_nome_primeira_interacao: false,
      __target_row_number_nome: null,
      __registro_nome: null,
      __motivo_nome: 'registro_nao_encontrado'
    }
  }];
}

const [rowNumber, row] = registros[0];
const disparo = minuto(row.disparo_inicial_em);
const ultima = minuto(row.ultima_interacao_em);
const nomePerfil = String(entrada.nome_contato_atual ?? '').replace(/\s+/g, ' ').trim();

// Regra solicitada: a análise de nome só acontece quando a última interação
// ainda é exatamente o horário do disparo inicial (mesmo minuto).
const primeiraInteracao = Boolean(disparo && ultima && disparo === ultima);
const deveAnalisar = primeiraInteracao && Boolean(nomePerfil);

return [{
  json: {
    ...entrada,
    __registro_encontrado_nome: true,
    __target_row_number_nome: rowNumber,
    __registro_nome: row,
    __disparo_minuto: disparo,
    __ultima_interacao_minuto: ultima,
    __primeira_interacao: primeiraInteracao,
    __analisar_nome_primeira_interacao: deveAnalisar,
    __nome_perfil_bruto: nomePerfil,
    __nome_decisor_atual: String(row.nome_decisor ?? '').trim(),
    __nome_fantasia: String(row.nome_fantasia ?? '').trim(),
    __motivo_nome: deveAnalisar
      ? 'primeira_interacao_com_nome_de_perfil'
      : (!primeiraInteracao ? 'nao_e_primeira_interacao' : 'nome_de_perfil_vazio')
  }
}];
